def gen(rng):
    def fmt(a, k):
        return f'{len(a)} {k}\n' + ' '.join(map(str, a))
    tests = [fmt([5], 1), fmt([5, 5], 1), fmt([5, 5], 2), fmt([-3, -3, -3], 3), fmt([1, 2, 3, 4], 1),
             fmt([7, 7, 7, 7], 2), fmt([4, 4, 9, 4, 4, 9], 2), fmt([-10**9, -10**9, 10**9], 2)]
    for n in (2, 4, 6, 9, 13, 20, 30):
        for _ in range(2):
            a = [rng.randint(-2, 2) for _ in range(n)]
            tests.append(fmt(a, rng.randint(1, min(n, 4))))
    N = 100000
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)], 1))
    runs = []
    while len(runs) < N:
        runs += [rng.randint(-10**9, 10**9)] * rng.randint(1, 4)
    tests.append(fmt(runs[:N], 2))
    tests.append(fmt([10**9] * N, N))
    tests.append(fmt([10**9] * (N - 1) + [-10**9], 1))
    return tests

